<?php declare(strict_types=1);require_once __DIR__.'/auth.php';$u=portal_require();$q=$db->prepare('SELECT client_id FROM client_portal_users WHERE id=?');$q->execute([$u['id']]);$client=(int)$q->fetchColumn();if($_SERVER['REQUEST_METHOD']==='POST'){$q=$db->prepare('INSERT INTO client_portal_messages(client_id,user_id,subject,message,direction) VALUES(?,?,?,?,"client")');$q->execute([$client,$u['id'],trim($_POST['subject']??''),trim($_POST['message'])]);header('Location: messages.php');exit;}$q=$db->prepare('SELECT subject,message,direction,created_at FROM client_portal_messages WHERE client_id=? ORDER BY created_at DESC');$q->execute([$client]);$rows=$q->fetchAll();?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Messages</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body><main class="container py-4"><a href="index.php">← Dashboard</a><h1 class="h3 mt-3">Messages</h1><form method="post" class="card card-body mb-4"><input class="form-control mb-2" name="subject" placeholder="Subject"><textarea class="form-control mb-2" name="message" placeholder="Message" required></textarea><button class="btn btn-dark">Send Message</button></form><?php foreach($rows as $r):?><div class="card mb-2"><div class="card-body"><b><?=htmlspecialchars($r['subject']??'Message')?></b><small class="d-block text-muted"><?=htmlspecialchars($r['direction'])?> · <?=htmlspecialchars($r['created_at'])?></small><p class="mb-0 mt-2"><?=nl2br(htmlspecialchars($r['message']))?></p></div></div><?php endforeach;?></main></body></html>